BEGIN;
INSERT INTO public.admin_users(id,email,password_hash,role,is_active) VALUES('f7700000-0000-4000-8000-000000000001','media-publication@example.test','test-only','admin',true);
INSERT INTO public.admin_sessions(id,admin_user_id,token_hash) VALUES('f7700000-0000-4000-8000-000000000002','f7700000-0000-4000-8000-000000000001',repeat('1',64));
DO $$ DECLARE actor uuid:='f7700000-0000-4000-8000-000000000001';sid uuid:='f7700000-0000-4000-8000-000000000002';t uuid;v jsonb;u uuid;f uuid;p uuid;j public.delivery_jobs;variants jsonb;BEGIN
 IF has_function_privilege('anon','public.read_public_gallery(uuid,integer)','EXECUTE') OR has_table_privilege('authenticated','public.media_derivatives','SELECT') THEN RAISE EXCEPTION 'Browser publication grant';END IF;
 INSERT INTO public.admin_teams(name,slug,created_by) VALUES('Fictional publication scope','fictional-publication-scope',actor) RETURNING id INTO t;
 v:=public.mutate_media_upload(actor,sid,NULL,'create',jsonb_build_object('teamId',t,'folderId',NULL,'filename','fixture.png','mime','image/png','bytes',100,'sha256',repeat('a',64),'key','quarantine/'||gen_random_uuid()||'/'||gen_random_uuid()),repeat('1',64),repeat('2',64),gen_random_uuid());u:=(v->>'uploadId')::uuid;f:=(v->>'fileId')::uuid;
 v:=public.mutate_media_upload(actor,sid,u,'complete','{}',repeat('3',64),repeat('2',64),gen_random_uuid());
 SELECT * INTO j FROM public.claim_worker_jobs(100,ARRAY['media_upload_scan']) WHERE payload->>'uploadId'=u::text;
 PERFORM public.reserve_media_scan_object(j.id,j.lease_token);
 PERFORM public.finish_media_upload_scan(j.id,j.lease_token,'clean/'||u||'/'||j.lease_token,'image/png',80,repeat('b',64),'{"width":10,"height":10}',NULL);
 BEGIN PERFORM public.mutate_media_publication(actor,sid,f,3,'publish','wrong',repeat('4',64),repeat('2',64),gen_random_uuid());RAISE EXCEPTION 'Unchecked credential';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 BEGIN PERFORM public.mutate_media_publication(actor,sid,f,3,'publish','test-only',repeat('4',64),repeat('2',64),gen_random_uuid());RAISE EXCEPTION 'Missing alt accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'MEDIA_PUBLICATION_BLOCKED' THEN RAISE;END IF;END;
 UPDATE public.media_files SET alt_text='Fictional coral image' WHERE id=f;
 v:=public.mutate_media_publication(actor,sid,f,3,'publish','test-only',repeat('4',64),repeat('2',64),gen_random_uuid());p:=(v->>'publicationId')::uuid;
 SELECT * INTO j FROM public.claim_worker_jobs(100,ARRAY['media_publish']) WHERE payload->>'publicationId'=p::text;
 IF public.prepare_media_publication(j.id,gen_random_uuid()) IS NOT NULL THEN RAISE EXCEPTION 'Forged preparation lease';END IF;
 v:=public.prepare_media_publication(j.id,j.lease_token);
 IF jsonb_array_length(v->'variants')<>3 OR public.read_public_media_asset(f,960,false) IS NOT NULL THEN RAISE EXCEPTION 'Quarantine derivatives became public';END IF;
 UPDATE public.media_files SET revision=revision+1 WHERE id=f;
 IF public.finish_media_publication(j.id,j.lease_token,'[]',NULL) THEN RAISE EXCEPTION 'Changed source promoted';END IF;
 IF(SELECT state FROM public.media_publications WHERE id=p)<>'failed' THEN RAISE EXCEPTION 'Stale approval not invalidated';END IF;
 v:=public.mutate_media_publication(actor,sid,f,4,'publish','test-only',repeat('5',64),repeat('2',64),gen_random_uuid());p:=(v->>'publicationId')::uuid;
 SELECT * INTO j FROM public.claim_worker_jobs(100,ARRAY['media_publish']) WHERE payload->>'publicationId'=p::text;
 v:=public.prepare_media_publication(j.id,j.lease_token);
 SELECT jsonb_agg(jsonb_build_object('widthKey',w,'width',10,'height',10,'bytes',80,'sha256',repeat('c',64))) INTO variants FROM unnest(ARRAY[360,960,1920]) w;
 IF NOT public.finish_media_publication(j.id,j.lease_token,variants,NULL) THEN RAISE EXCEPTION 'Publication not promoted';END IF;
 IF public.read_public_media_asset(f,960,false) IS NULL OR public.read_public_media_asset(f,960,true) IS NOT NULL OR(public.read_public_gallery(NULL,1)->>'total')::integer<>1 THEN RAISE EXCEPTION 'Public asset/download contract';END IF;
 IF(SELECT verified_hash FROM public.media_publications WHERE id=p) IS NOT NULL THEN RAISE EXCEPTION 'Approval password hash retained after work';END IF;
 v:=public.mutate_media_publication(actor,sid,f,5,'revoke','test-only',repeat('6',64),repeat('2',64),gen_random_uuid());
 IF public.read_public_media_asset(f,960,false) IS NOT NULL OR(public.read_public_gallery(NULL,1)->>'total')::integer<>0 THEN RAISE EXCEPTION 'Revoke still public';END IF;
 UPDATE public.media_files SET is_public=true,publication_id=NULL WHERE id=f;
 IF public.read_public_media_asset(f,960,false) IS NOT NULL THEN RAISE EXCEPTION 'Legacy flag bypassed approval';END IF;
END $$;
ROLLBACK;
